/* ========================================================================== */
/* BFUSION Financial Overview                                                  */
/* Header / insight strip / insight panel ported from the suite reference     */
/* (bfusion-ResourceGapAnalysis), prefix rga- → fov-.                         */
/* ========================================================================== */
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
/***********************************************************
 * 1. Base Structure
 ***********************************************************/
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
  color: var(--bf-text, #242424);
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.fov-root {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
/* Header bar (title + subtitle + info button) */
.fov-header {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 16px 6px 16px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  position: relative;
}
.fov-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.fov-header__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fov-header__subtitle {
  margin-top: 2px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fov-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  padding: 0;
  transition: all 0.15s ease;
}
.fov-header__info:hover,
.fov-header__info:focus-visible {
  color: var(--bf-tile, #FFFFFF);
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.fov-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.fov-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 300px;
  max-width: calc(100% - 24px);
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: var(--bf-text, #242424);
  line-height: 1.45;
}
.fov-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.fov-header__info-pop ul li {
  margin: 3px 0;
  color: var(--bf-muted, #667079);
}
.fov-info-pop__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  margin-bottom: 4px;
}
.fov-info-pop__desc {
  color: var(--bf-muted, #667079);
}
/* Toolbar (on-canvas Status Date picker) */
.fov-toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 16px;
  background: var(--bf-surface, #F8F9FB);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  font-size: 11px;
  color: var(--bf-muted, #667079);
}
.fov-toolbar__label {
  flex: 0 0 auto;
  font-size: 9.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--bf-muted, #667079);
  white-space: nowrap;
  cursor: pointer;
}
.fov-toolbar__date {
  flex: 0 0 auto;
  font: inherit;
  font-size: 11px;
  color: var(--bf-text, #242424);
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 10px;
  padding: 1px 8px;
  accent-color: #E8612A;
}
.fov-toolbar__date:focus {
  outline: none;
  border-color: #E8612A;
}
.fov-toolbar__hint {
  min-width: 0;
  font-size: 10px;
  color: var(--bf-muted, #667079);
  font-style: italic;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fov-toolbar__hint--warn {
  color: var(--bf-hint-text, #92400E);
  font-style: normal;
  font-weight: 600;
}
/* Body row: chart + insight strip + insight panel */
.fov-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
  position: relative;
}
.fov-chart-col {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  overflow: hidden;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--bf-bg, #FFFFFF);
}
.fov-plot {
  flex: 1 1 auto;
  min-height: 0;
  position: relative;
}
/* Legend — centered under (or above) the chart */
.fov-legend {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 3px 14px;
  padding: 2px 12px 4px;
  color: var(--bf-muted, #667079);
  line-height: 1.3;
  user-select: none;
}
.fov-legend--top {
  padding: 6px 12px 0;
}
.fov-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.fov-legend__swatch {
  flex: 0 0 auto;
  display: block;
}
/* On-chart callouts */
.fov-callout {
  cursor: help;
}
.fov-callout text {
  pointer-events: none;
}
/* ========================================================================== */
/* Insight Panel (right-side) — collapsed strip + expanded panel              */
/* ========================================================================== */
.fov-insight-strip {
  flex: 0 0 26px;
  width: 26px;
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.fov-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.fov-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-weight: 650;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  font-size: 9px;
}
.fov-insight-strip:hover,
.fov-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.fov-insight-strip:focus-visible {
  box-shadow: inset 0 0 0 2px var(--fov-insight-accent, #E8612A);
}
.fov-insight-panel {
  flex: 0 0 250px;
  max-width: 280px;
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  display: flex;
  flex-direction: column;
  padding: 12px 12px 16px 12px;
  overflow-y: auto;
  font-size: var(--fov-insight-font, 11px);
  color: var(--bf-text, #242424);
  gap: 10px;
}
.fov-insight-panel::-webkit-scrollbar {
  width: 5px;
}
.fov-insight-panel::-webkit-scrollbar-thumb {
  background: var(--bf-scroll-thumb, #D0D0D0);
  border-radius: 3px;
}
.fov-insight-panel::-webkit-scrollbar-track {
  background: transparent;
}
.fov-insight-panel__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--fov-insight-accent, #E8612A);
}
.fov-insight-panel__title {
  font-size: var(--fov-insight-header-font, 12px);
  font-weight: 700;
  color: var(--bf-text, #242424);
  letter-spacing: 0.2px;
}
.fov-insight-panel__subtitle {
  font-size: calc(var(--fov-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
}
.fov-insight-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.fov-insight-panel__section {
  margin-top: 2px;
}
.fov-insight-panel__section-title {
  font-weight: 600;
  color: var(--bf-muted, #667079);
  font-size: calc(var(--fov-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.fov-insight-panel__more {
  margin-top: 4px;
  font-size: calc(var(--fov-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  font-style: italic;
}
.fov-insight-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.fov-insight-panel__list li {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 4px;
  margin-bottom: 2px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
}
.fov-insight-panel__dot {
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.95);
}
.fov-insight-panel__name {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fov-insight-panel__val {
  flex: 0 0 auto;
  font-weight: 600;
  color: var(--bf-muted, #667079);
  font-variant-numeric: tabular-nums;
}
.fov-kpi {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--fov-kpi-color, #E8612A);
  border-radius: 6px;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.fov-kpi:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);
}
.fov-kpi__value {
  font-size: calc(var(--fov-insight-font, 11px) + 3px);
  font-weight: 700;
  color: var(--fov-kpi-color, var(--bf-text, #242424));
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fov-kpi__label {
  font-size: calc(var(--fov-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  line-height: 1.25;
}
/* Status verdict */
.fov-verdict {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--fov-sev, #E8612A);
  border-radius: 6px;
  padding: 7px 9px;
}
.fov-verdict__label {
  font-size: calc(var(--fov-insight-font, 11px) + 1px);
  font-weight: 800;
  letter-spacing: 0.6px;
  color: var(--fov-sev, var(--bf-text, #242424));
}
.fov-verdict__text {
  margin-top: 2px;
  line-height: 1.4;
  color: var(--bf-text, #242424);
}
/* Budget consumed vs plan */
.fov-gauge {
  position: relative;
  height: 8px;
  border-radius: 4px;
  background: var(--bf-rule, #E5E7EB);
}
.fov-gauge__fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.35s ease;
}
.fov-gauge__marker {
  position: absolute;
  top: -3px;
  width: 2px;
  height: 14px;
  margin-left: -1px;
  border-radius: 1px;
  background: var(--bf-strong, #1F2A44);
  opacity: 0.7;
}
.fov-gauge__caption {
  margin-top: 5px;
  font-size: calc(var(--fov-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
}
.fov-gauge__caption strong {
  color: var(--bf-text, #242424);
}
/* Decision points */
.fov-decisions {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.fov-decision {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--fov-sev, #E8612A);
  border-radius: 6px;
  padding: 6px 8px;
  line-height: 1.4;
}
.fov-decision__title {
  font-weight: 700;
  color: var(--fov-sev, var(--bf-text, #242424));
}
.fov-decision__finding {
  margin-top: 2px;
  color: var(--bf-text, #242424);
}
.fov-decision__action {
  margin-top: 4px;
  padding-top: 4px;
  border-top: 1px dashed var(--bf-rule, #E5E7EB);
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
}
.fov-decision__arrow {
  color: var(--fov-insight-accent, #E8612A);
  margin-right: 4px;
}
.fov-hint {
  background: var(--bf-hint-bg, #FFFBEB);
  border: 1px solid var(--bf-hint-border, #FDE68A);
  border-radius: 6px;
  padding: 6px 8px;
  color: var(--bf-hint-text, #92400E);
  line-height: 1.4;
  font-size: calc(var(--fov-insight-font, 11px) - 1px);
}
.fov-hint strong {
  color: var(--bf-hint-text, #92400E);
}
/* Insight panel visibility states */
.fov-body--insight-collapsed .fov-insight-panel {
  display: none;
}
.fov-body--insight-hidden .fov-insight-panel,
.fov-body--insight-hidden .fov-insight-strip {
  display: none;
}
/* ========================================================================== */
/* Responsive width classes                                                   */
/* ========================================================================== */
.fov-medium .fov-insight-panel {
  flex-basis: 220px;
}
.fov-narrow .fov-insight-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 0;
  width: 240px;
  z-index: 25;
  box-shadow: -6px 0 18px rgba(15, 23, 42, 0.1);
}
.fov-narrow .fov-header__title {
  font-size: 12px !important;
}
.fov-narrow .fov-toolbar {
  padding: 4px 10px;
  gap: 6px;
}
.fov-narrow .fov-toolbar__hint {
  display: none;
}
/***********************************************************
 * 2. Landing Page
 ***********************************************************/
.bfusion-landing-wrap {
  width: 100%;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
}
.bfusion-landing__metadata a {
  color: var(--bf-muted, #667079);
  text-decoration: none;
}
.bfusion-landing__metadata a:hover {
  text-decoration: underline;
}
/***********************************************************
 * 3. Tooltip
 ***********************************************************/
.bfusion-tooltip {
  line-height: 1.5;
  color: var(--bf-text, #242424);
}
.bfusion-tooltip div {
  margin-bottom: 1px;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
/* The badge sits in the 24px clear-zone under the chart, never on the axis.
   Discreet but readable: no fill, no border, dark grey text. Scoped under the
   root so it outranks the badge CSS that license.ts injects at runtime. */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
  line-height: 1;
}
.bfusion-root .bfusion-license-badge {
  position: static;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  color: var(--bf-badge, #4B5563);
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-root .bfusion-license-badge em {
  color: #E8612A;
  font-style: normal;
  font-weight: 600;
  opacity: 1;
}
.bfusion-license-badge__icon {
  font-size: 10px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/***********************************************************
 * Chart area + data table (Financial Overview)
 ***********************************************************/
.fov-chart-area {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.fov-table-wrap {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  position: relative;
  border-top: 2px solid var(--bf-rule, #E5E7EB);
}
.fov-table-wrap::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.fov-table-wrap::-webkit-scrollbar-thumb {
  background: var(--bf-scroll-thumb, #D0D0D0);
  border-radius: 3px;
}
.fov-table-wrap::-webkit-scrollbar-thumb:hover {
  background: var(--bf-muted, #667079);
}
.fov-table-wrap::-webkit-scrollbar-track {
  background: var(--bf-surface-alt, #F4F5F7);
}
.bfusion-data-table {
  border-spacing: 0;
}
.bfusion-data-table tbody tr:hover td {
  background-color: var(--bf-surface-alt, #F4F5F7) !important;
}
.bfusion-data-table .fov-sticky {
  box-shadow: 2px 0 4px rgba(0, 0, 0, 0.04);
}
.fov-spark {
  display: inline-block;
  margin-left: 10px;
  vertical-align: middle;
}
